    links.extend([dict(source='CHO2025', source_locator='inputs/CHO_SENSOR.json; T4/T5', target='O01 measured wrench calibration', quantity='Six-axis baseline-referenced wrench', resolution_level='PER_TOOTH', time_scale='SIMULTANEOUS', semantics='Separate material/tooth/fabrication group and source root-apex origin; no transfer to unknown crown origin'), dict(source='LOAD_SPECIFIC_COUPONS', source_locator='inputs/RELAXATION.json indices101/122', target='O01 conditional relaxed stiffness state', resolution_level='PHENOMENOLOGICAL', time_scale='HANDOVER', semantics='Different load cases retained; transfer to formed shell unknown; unloaded aging rejected')])
    links.append(dict(source='KAUR_THESIS_TABLE4.4', source_locator=r6['external_referent']['locator'], target='O01 adjacent-tooth signed reaction validation', quantity='Neighbour Fy force N', resolution_level='PER_TOOTH', time_scale='SIMULTANEOUS', semantics='Six individual tooth-response pairs; no arch mean; Taglus sensor shell distinct from Park Duran'))
